-- Frey Ranch importer (bourbon.frey_ranch, freyranch.com + shop.freyranch.com) — applied 2026-10-11 via Supabase MCP execute_sql.
-- part 1: Straight Bourbon age 4->5 and confirmed; Farm Strength Uncut Rye confirmed (124.5, 6 yr); Farm Strength Uncut Bourbon (range, listed not confirmed) and 100% Barley (no proof, listed) promoted/stamped; then 2 additions (Bottled in Bond Straight Rye, Single Grain Series 100% Wheat).
update cellar.products set age_years = 5.0, age_label = '5 yr', nas = false, producer = coalesce(producer, 'Frey Ranch'), producer_id = coalesce(producer_id, 'cf847398-948d-411d-af87-e2b53b73981f'::uuid), source = 'maker', status = 'confirmed', source_url = 'https://freyranch.com/straight-bourbon-whiskey/', source_checked_at = now(), discontinued = false, is_core_range = true, catalog_included = true, rarity = coalesce(rarity, 'shelf'::cellar.rarity) where id = '237ed494-6176-4a25-813e-61349ab2d814' and facts_verified_at is null;
update cellar.products set specs = coalesce(specs, '{}'::jsonb) || jsonb_build_object('source_image_url', 'https://cdn.shopify.com/s/files/1/0640/4639/9708/files/bottle-awards-product-image-FR-Rye.png?v=1781029714'), producer = coalesce(producer, 'Frey Ranch'), producer_id = coalesce(producer_id, 'cf847398-948d-411d-af87-e2b53b73981f'::uuid), source = 'maker', status = 'confirmed', source_url = 'https://shop.freyranch.com/products/frey-ranch-farm-strength-rye', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range, rarity = coalesce(rarity, 'limited'::cellar.rarity) where id = 'e8a591f3-333e-4184-8299-abbf629bb6fd' and facts_verified_at is null;
update cellar.products set specs = coalesce(specs, '{}'::jsonb) || jsonb_build_object('source_image_url', 'https://cdn.shopify.com/s/files/1/0640/4639/9708/files/Barley-product-image.png?v=1783956186'), producer = coalesce(producer, 'Frey Ranch'), producer_id = coalesce(producer_id, 'cf847398-948d-411d-af87-e2b53b73981f'::uuid), source_url = 'https://shop.freyranch.com/products/100-barley-375ml-vault', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range, rarity = coalesce(rarity, 'limited'::cellar.rarity) where id = '2e259a05-15e9-4a9d-aea9-b2f88ee5643e' and facts_verified_at is null;
update cellar.products set source_checked_at = now() where id in ('55c8d851-ff88-44b6-9adf-d587216d1ba5', '237ed494-6176-4a25-813e-61349ab2d814', 'e8a591f3-333e-4184-8299-abbf629bb6fd', '2e259a05-15e9-4a9d-aea9-b2f88ee5643e');
update cellar.products set source_url = 'https://freyranch.com/farm-strength-uncut-bourbon/', discontinued = false, is_core_range = true, catalog_included = true, rarity = coalesce(rarity, 'limited'::cellar.rarity), producer = coalesce(producer, 'Frey Ranch'), producer_id = coalesce(producer_id, 'cf847398-948d-411d-af87-e2b53b73981f'::uuid), specs = coalesce(specs, '{}'::jsonb) || jsonb_build_object('source_image_url', 'https://freyranch.com/wp-content/uploads/2023/06/farm-strength-uncut-whiskey.png') where id = '55c8d851-ff88-44b6-9adf-d587216d1ba5' and facts_verified_at is null;
insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"Frey Ranch Bottled in Bond Straight Rye","rar":"shelf","f":"Frey Ranch","x":"Bottled in Bond Straight Rye","p":100.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"rye","mb":"100% Winter Cereal Rye","st":"rye","bib":true,"bp":false,"fin":null,"msrp":null,"core":true,"al2":["Frey Ranch Bottled-in-Bond Straight Rye Whiskey","Frey Ranch Straight Rye"],"img":"https://freyranch.com/wp-content/uploads/2022/09/frey-ranch-straight-rye-whiskey.gif","u":"https://freyranch.com/straight-rye-whiskey/","pr":"Frey Ranch","mk":"cf847398-948d-411d-af87-e2b53b73981f"},{"n":"Frey Ranch Single Grain Series 100% Wheat","rar":"limited","f":"Frey Ranch","x":"Single Grain Series 100% Wheat","p":120.0,"ay":4.67,"al":"4.67 yr","nas":false,"et":"standard","ms":"wheated","mb":"100% Soft White Winter Wheat","st":"wheat_whiskey","bib":false,"bp":true,"fin":null,"msrp":null,"core":false,"al2":["Frey Ranch 100% Wheat Whiskey"],"img":"https://cdn.shopify.com/s/files/1/0640/4639/9708/files/wheat.png?v=1739203709","u":"https://shop.freyranch.com/products/100-wheat-whiskey-vault","pr":"Frey Ranch","mk":"cf847398-948d-411d-af87-e2b53b73981f"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');
